style.css:
@-moz-document domain("youtube.com") {
/* Main background */
  body {
    background: linear-gradient(
      135deg,
      #dffaff,
      #b4edff,
      #e8fcff
    ) !important;
    color: #164b70 !important;
  }

  /* Header */
  ytd-masthead {
    background: linear-gradient(
      180deg,
      #ffffff,
      #c5f3ff
    ) !important;
    border-bottom: 1px solid #8cddf5 !important;
    box-shadow: 0 4px 15px #66cfff66 !important;
  }

  /* Search bar */
  #container.ytd-searchbox {
    background: linear-gradient(
      180deg,
      #ffffff,
      #c5f2ff
    ) !important;
    border: 1px solid #8bdcf5 !important;
    border-radius: 30px !important;
    box-shadow: inset 0 2px 5px #ffffff,
                0 3px 10px #62cfff55 !important;
  }

  /* Search button */
  ytd-searchbox button {
    background: linear-gradient(
      #e9fcff,
      #8ddfff
    ) !important;
    border-radius: 0 30px 30px 0 !important;
  }

  /* Video thumbnails */
  ytd-thumbnail {
    border-radius: 18px !important;
    overflow: hidden !important;
    box-shadow: 0 5px 15px #42b9ed55 !important;
    transition: 0.3s ease !important;
  }

  ytd-thumbnail:hover {
    transform: translateY(-4px) scale(1.02);
    box-shadow: 0 8px 25px #26b9ff88 !important;
  }

  /* Video cards */
  ytd-rich-item-renderer,
  ytd-compact-video-renderer {
    border-radius: 18px !important;
  }

  /* Sidebar */
  ytd-mini-guide-renderer,
  ytd-guide-renderer {
    background: linear-gradient(
      180deg,
      #e9fcff,
      #c9f2ff
    ) !important;
  }

  /* Buttons */
  yt-button-shape-next button {
    border-radius: 25px !important;
    background: linear-gradient(
      180deg,
      #ffffff,
      #a7e8ff
    ) !important;
    box-shadow: 0 3px 9px #55caff55 !important;
  }

  /* Chips */
  yt-chip-cloud-chip-renderer {
    border-radius: 25px !important;
    background: linear-gradient(
      180deg,
      #ffffff,
      #b6edff
    ) !important;
    border: 1px solid #91ddf5 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(
      #b6f1ff,
      #36b9ec
    );
    border-radius: 20px;
  }

  /* Selection */
  ::selection {
    background: #65d8ff;
    color: #ffffff;
  }
}
